package com.smeventaura.backend.controller;import com.smeventaura.backend.dto.ContactDto;import com.smeventaura.backend.model.ContactMessage;import com.smeventaura.backend.repository.ContactMessageRepository;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/api/contact") public class ContactController{final ContactMessageRepository repo;ContactController(ContactMessageRepository r){repo=r;}@PostMapping public ResponseEntity<?> create(@RequestBody ContactDto d){if(d.name()==null||d.phone()==null||d.message()==null||d.message().isBlank())return ResponseEntity.badRequest().body(Map.of("message","Please complete all fields."));ContactMessage m=new ContactMessage();m.setName(d.name().trim());m.setPhone(d.phone().trim());m.setMessage(d.message().trim());repo.save(m);return ResponseEntity.ok(Map.of("message","Message received."));}}
